/// <summary>
/// Builds the setup MD31 validates, with ATL, and points the MD31 parameters at it.
/// The model group and unit are the ones ATL gives its own items, so updating an
/// existing ATL item changes neither; the item group is a separate one, so the
/// item-group rule is visible.
/// </summary>
public void setUp()
{
    super();

    data   = AtlDataRootNode::construct();
    invent = data.invent();
    md31   = data.md31();

    storageGroup  = invent.storageDimGroups().default();
    trackingGroup = invent.trackingDimGroups().default();
    modelGroup    = invent.modelGroups().default().record();
    unit          = invent.units().default();
    itemGroup     = invent.itemGroups().findOrCreate(#TestItemGroup);

    data.common().addressCountryRegions().findOrCreate(#TestCountry, #TestCountryIso);

    md31.setParameters(storageGroup.Name,
                       trackingGroup.Name,
                       modelGroup.ModelGroupId,
                       itemGroup.ItemGroupId,
                       unit.Symbol,
                       #NullDateLiteral);
}

/// <summary>
/// TC01: a new SKU with every mapped field filled. The product is created and released
/// with the configured groups and unit, the fields are mapped, the row is archived as
/// Created and removed from the input table.
/// TaraWeight: applyItemAttributes writes oc_gross_weight to InventTable.TaraWeight; the
/// class header says GrossWeight. This test pins the code - confirm which one is right.
/// </summary>
[SysTestMethod]
public void tc01_newSku_isCreatedReleasedAndArchived()
{
    const Filename               TestFile = 'TEST_MD31_TC01';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC01S001';

    this.assertSkuIsFree(Sku);
    this.initFullRow(TestFile, Sku).save();

    this.process(TestFile);

    this.assertArchivedOnly(TestFile, Sku, SJPMDInventImportStatus::Created);

    invent.items().query().withItemId(Sku).assertExpectedLinesSet(AtlSpecifications::construct()
        .addSpec(md31.releasedItemSpec()
            .withItemId(Sku)
            .withNameAlias(Sku)
            .withNetWeight(1.2)
            .withTaraWeight(1.5)
            .withGrossSize(30.5, 20, 10)
            .withUnitVolume(24)
            .withBOMUnitId(unit.Symbol)
            .withOrigCountryRegionId(#TestCountry)
            .withParentJanFlag(NoYes::Yes)
            .withDepartmentCode('D01')
            .withProductCategory('CAT1')),
        'Released product after MD31');

    this.assertEquals('MD31 test ' + Sku, this.productName(Sku, 'en-us'), 'English product name');
    this.assertEquals('Local name', this.productName(Sku, 'ja'), 'Japanese product name');

    this.assertModule(Sku, ModuleInventPurchSales::Sales,  108);
    this.assertModule(Sku, ModuleInventPurchSales::Invent, 0);
    this.assertModule(Sku, ModuleInventPurchSales::Purch,  0);

    this.assertEquals(itemGroup.ItemGroupId, this.itemGroupOf(Sku), 'Item group from the MD31 parameters');
    this.assertEquals(modelGroup.ModelGroupId, this.modelGroupOf(Sku), 'Model group from the MD31 parameters');
    this.assertEquals(storageGroup.RecId, this.storageGroupOf(Sku), 'Storage dimension group from the MD31 parameters');
    this.assertEquals(trackingGroup.RecId, this.trackingGroupOf(Sku), 'Tracking dimension group from the MD31 parameters');
}

/// <summary>
/// TC02: the SKU is already a released product (created with ATL) without inventory
/// transactions. MD31 updates it (archive Status Updated), maps the new values and
/// moves it to the configured item group.
/// </summary>
[SysTestMethod]
public void tc02_existingItem_isUpdatedAndItemGroupSwitched()
{
    const Filename               TestFile = 'TEST_MD31_TC02';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC02S001';

    this.assertSkuIsFree(Sku);
    this.createExistingItem(Sku);
    this.assertNotEqual(itemGroup.ItemGroupId, this.itemGroupOf(Sku), 'Arrange: the ATL item must start in another item group');

    md31.initRow(TestFile, Sku).setCaseWeights(2.0, 2.5).save();

    this.process(TestFile);

    this.assertArchivedOnly(TestFile, Sku, SJPMDInventImportStatus::Updated);

    invent.items().query().withItemId(Sku).assertExpectedLinesSet(AtlSpecifications::construct()
        .addSpec(md31.releasedItemSpec().withItemId(Sku).withNetWeight(2.0).withTaraWeight(2.5)),
        'Existing item after MD31');

    this.assertEquals(itemGroup.ItemGroupId, this.itemGroupOf(Sku), 'Without inventory transactions the item moves to the configured item group');
}

/// <summary>
/// TC03: the existing item already has inventory transactions (an ATL adjustment
/// journal posted on-hand). MD31 still updates it, but ensureItemGroupInCompany keeps
/// its item group.
/// </summary>
[SysTestMethod]
public void tc03_existingItemWithTransactions_keepsItemGroup()
{
    const Filename               TestFile = 'TEST_MD31_TC03';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC03S001';
    InventTrans                  inventTrans;

    this.assertSkuIsFree(Sku);
    InventTable item = this.createExistingItem(Sku);
    ItemGroupId originalGroup = this.itemGroupOf(Sku);

    // postJournal() builds the journal directly, without the ensure hooks of
    // adjustmentJournals().initDefault(); set up journal and posting prerequisites first,
    // as AtlWHSEWTestCase does for a new company.
    invent.adjustmentJournals().ensureCanCreate();
    invent.adjustmentJournals().ensureCanPost();

    invent.onHand().adjust()
        .forItem(item)
        .forWarehouse(invent.warehouses().default())
        .setQty(5)
        .setPostedValue(50)
        .postJournal();

    select firstonly RecId from inventTrans where inventTrans.ItemId == Sku;
    this.assertTrue(inventTrans.RecId != 0, 'Arrange: the posted adjustment must have created inventory transactions');

    md31.initRow(TestFile, Sku).save();

    this.process(TestFile);

    this.assertArchivedOnly(TestFile, Sku, SJPMDInventImportStatus::Updated);
    this.assertEquals(originalGroup, this.itemGroupOf(Sku), 'An item with inventory transactions keeps its item group');
}

/// <summary>
/// TC04: sku_name_en is mandatory. The SKU ends in Error with the flag and a message,
/// nothing is archived and no product is created.
/// </summary>
[SysTestMethod]
public void tc04_missingEnglishName_skuInError()
{
    const Filename               TestFile = 'TEST_MD31_TC04';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC04S001';

    this.assertSkuIsFree(Sku);
    md31.initRow(TestFile, Sku).setNameEnglish('').save();

    this.process(TestFile);

    this.assertSkuInError(TestFile, Sku, 1);
}

/// <summary>
/// TC05: a negative price fails validation.
/// </summary>
[SysTestMethod]
public void tc05_negativePrice_skuInError()
{
    const Filename               TestFile = 'TEST_MD31_TC05';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC05S001';

    this.assertSkuIsFree(Sku);
    md31.initRow(TestFile, Sku).setPrice(-1).save();

    this.process(TestFile);

    this.assertSkuInError(TestFile, Sku, 1);
}

/// <summary>
/// TC06: sel_tm_bg is not a calendar date (month 13).
/// </summary>
[SysTestMethod]
public void tc06_invalidSellDate_skuInError()
{
    const Filename               TestFile = 'TEST_MD31_TC06';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC06S001';

    this.assertSkuIsFree(Sku);
    md31.initRow(TestFile, Sku).setSellStart('20261301').save();

    this.process(TestFile);

    this.assertSkuInError(TestFile, Sku, 1);
}

/// <summary>
/// TC07: two valid dates, but the sell start is after the sell end.
/// </summary>
[SysTestMethod]
public void tc07_sellStartAfterEnd_skuInError()
{
    const Filename               TestFile = 'TEST_MD31_TC07';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC07S001';

    this.assertSkuIsFree(Sku);
    md31.initRow(TestFile, Sku).setSellStart('20271231').setSellEnd('20270101').save();

    this.process(TestFile);

    this.assertSkuInError(TestFile, Sku, 1);
}

/// <summary>
/// TC08: a country of origin that does not exist in LogisticsAddressCountryRegion.
/// </summary>
[SysTestMethod]
public void tc08_unknownCountry_skuInError()
{
    const Filename               TestFile = 'TEST_MD31_TC08';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC08S001';
    const str                    Unknown  = 'ZZZ';

    this.assertSkuIsFree(Sku);
    this.assertFalse(LogisticsAddressCountryRegion::exist(Unknown), 'Arrange: country ZZZ must not exist');
    md31.initRow(TestFile, Sku).setCountryOfOrigin(Unknown).save();

    this.process(TestFile);

    this.assertSkuInError(TestFile, Sku, 1);
}

/// <summary>
/// TC09: both sell dates carry the configured null-date literal. They pass validation
/// and are not written, so the sell dates stay empty.
/// </summary>
[SysTestMethod]
public void tc09_nullDateLiteral_isCreatedWithoutSellDates()
{
    const Filename               TestFile = 'TEST_MD31_TC09';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC09S001';

    this.assertSkuIsFree(Sku);
    md31.initRow(TestFile, Sku).setSellStart(#NullDateLiteral).setSellEnd(#NullDateLiteral).save();

    this.process(TestFile);

    this.assertArchivedOnly(TestFile, Sku, SJPMDInventImportStatus::Created);

    MCRInventTable mcrInventTable = this.mcrInventTableOf(Sku);
    this.assertEquals(dateNull(), mcrInventTable.SellStartDate, 'Sell start stays empty for the null-date literal');
    this.assertEquals(dateNull(), mcrInventTable.SellEndDate, 'Sell end stays empty for the null-date literal');
}

/// <summary>
/// TC10: valid sell dates are parsed from YYYYMMDD and written to MCRInventTable.
/// </summary>
[SysTestMethod]
public void tc10_sellDates_areWrittenToMcrInventTable()
{
    const Filename               TestFile = 'TEST_MD31_TC10';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC10S001';

    this.assertSkuIsFree(Sku);
    md31.initRow(TestFile, Sku).setSellStart('20261101').setSellEnd('20271031').save();

    this.process(TestFile);

    this.assertArchivedOnly(TestFile, Sku, SJPMDInventImportStatus::Created);

    MCRInventTable mcrInventTable = this.mcrInventTableOf(Sku);
    this.assertEquals(mkDate(1, 11, 2026), mcrInventTable.SellStartDate, 'Sell start from sel_tm_bg');
    this.assertEquals(mkDate(31, 10, 2027), mcrInventTable.SellEndDate, 'Sell end from sel_tm_en');
}

/// <summary>
/// TC11: rel_flag = 1 sets RetailInventTable.blockedOnPOS. The standard InventTable.insert
/// creates the RetailInventTable row only when the Retail configuration key is on.
/// </summary>
[SysTestMethod]
public void tc11_posBlockFlag_blocksItemOnPos()
{
    const Filename               TestFile = 'TEST_MD31_TC11';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC11S001';
    RetailInventTable            retailInventTable;

    this.assertTrue(isConfigurationkeyEnabled(configurationKeyNum(Retail)), 'Arrange: the Retail configuration key must be on for RetailInventTable to exist');
    this.assertSkuIsFree(Sku);
    md31.initRow(TestFile, Sku).setPosBlockFlag(1).save();

    this.process(TestFile);

    this.assertArchivedOnly(TestFile, Sku, SJPMDInventImportStatus::Created);

    select firstonly retailInventTable where retailInventTable.ItemId == Sku;
    this.assertTrue(retailInventTable.RecId != 0, 'The release must have created RetailInventTable');
    this.assertEquals(NoYes::Yes, retailInventTable.blockedOnPOS, 'rel_flag 1 blocks the item on POS');
}

/// <summary>
/// TC12: two SKUs in one file, one with a negative price. Errors are isolated per SKU:
/// the bad one ends in Error, the good one is created and archived.
/// </summary>
[SysTestMethod]
public void tc12_oneBadSku_otherSkuInSameFileIsCreated()
{
    const Filename               TestFile = 'TEST_MD31_TC12';
    const SJPMDItemMasterJANCode GoodSku  = 'ZT31TC12S001';
    const SJPMDItemMasterJANCode BadSku   = 'ZT31TC12S002';

    this.assertSkuIsFree(GoodSku);
    this.assertSkuIsFree(BadSku);
    md31.initRow(TestFile, GoodSku).save();
    md31.initRow(TestFile, BadSku).setPrice(-1).save();

    this.process(TestFile);

    md31.archive().forFileName(TestFile).assertExpectedLinesSet(AtlSpecifications::construct()
        .addSpec(md31.archiveSpec().withSkuCode(GoodSku).withStatus(SJPMDInventImportStatus::Created)),
        'Only the good SKU is archived');

    md31.rows().forFileName(TestFile).assertExpectedLinesSet(AtlSpecifications::construct()
        .addSpec(md31.rowSpec().withSkuCode(BadSku).withStatus(SJPMDInventImportStatus::Error).withErrorFlag(NoYes::Yes)),
        'Only the bad SKU is left, in Error');

    this.assertTrue(InventTable::exist(GoodSku), 'The good SKU is released');
    this.assertFalse(this.productExists(BadSku), 'No product is created for the bad SKU');
}

/// <summary>
/// TC13: processGroup filters by file name. Processing file A leaves file B at New.
/// </summary>
[SysTestMethod]
public void tc13_fileFilter_otherFileStaysNew()
{
    const Filename               FileA = 'TEST_MD31_TC13_A';
    const Filename               FileB = 'TEST_MD31_TC13_B';
    const SJPMDItemMasterJANCode SkuA  = 'ZT31TC13S001';
    const SJPMDItemMasterJANCode SkuB  = 'ZT31TC13S002';

    this.assertSkuIsFree(SkuA);
    this.assertSkuIsFree(SkuB);
    md31.initRow(FileA, SkuA).save();
    md31.initRow(FileB, SkuB).save();

    this.process(FileA);

    this.assertArchivedOnly(FileA, SkuA, SJPMDInventImportStatus::Created);

    md31.rows().forFileName(FileB).assertExpectedLinesSet(AtlSpecifications::construct()
        .addSpec(md31.rowSpec().withSkuCode(SkuB).withStatus(SJPMDInventImportStatus::New)),
        'File B was not selected and stays at New');
    this.assertFalse(this.productExists(SkuB), 'No product is created for file B');
}

/// <summary>
/// TC14: the parameters lack a default model group. validateParameters reports it and
/// every SKU of the run ends in Error.
/// </summary>
[SysTestMethod]
public void tc14_missingParameter_skuInError()
{
    const Filename               TestFile = 'TEST_MD31_TC14';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC14S001';

    md31.setParameters(storageGroup.Name, trackingGroup.Name, '', itemGroup.ItemGroupId, unit.Symbol, #NullDateLiteral);

    this.assertSkuIsFree(Sku);
    md31.initRow(TestFile, Sku).save();

    this.process(TestFile);

    this.assertSkuInError(TestFile, Sku, 1);
}

/// <summary>
/// TC15: two rows of the same SKU in one file (different crp_cd, as the unique index
/// file_name + crp_cd + sku_cd requires). They form one partition: one product, and
/// both rows archived as Created.
/// </summary>
[SysTestMethod]
public void tc15_twoRowsSameSku_areArchivedTogether()
{
    const Filename               TestFile = 'TEST_MD31_TC15';
    const SJPMDItemMasterJANCode Sku      = 'ZT31TC15S001';
    EcoResDistinctProduct        product;

    this.assertSkuIsFree(Sku);
    md31.initRow(TestFile, Sku).setCompanyCode('TEST1').save();
    md31.initRow(TestFile, Sku).setCompanyCode('TEST2').save();

    this.process(TestFile);

    md31.archive().forFileName(TestFile).assertExpectedLinesSet(AtlSpecifications::construct()
        .addSpec(md31.archiveSpec().withSkuCode(Sku).withCompanyCode('TEST1').withStatus(SJPMDInventImportStatus::Created))
        .addSpec(md31.archiveSpec().withSkuCode(Sku).withCompanyCode('TEST2').withStatus(SJPMDInventImportStatus::Created)),
        'Both rows of the SKU are archived');
    md31.rows().forFileName(TestFile).assertCount(0, 'No input row is left');

    select count(RecId) from product where product.DisplayProductNumber == Sku;
    this.assertTrue(product.RecId == 1, strFmt('Expected one product for the SKU, found %1', product.RecId));
}

/// <summary>
/// TC16: countPendingRows, which SJPMDItemMasterImportBatchTask uses to fail a group that
/// left rows behind, counts only New rows of the given group and file.
/// </summary>
[SysTestMethod]
public void tc16_countPendingRows_filtersGroupAndFile()
{
    const Filename FileA = 'TEST_MD31_TC16_A';
    const Filename FileB = 'TEST_MD31_TC16_B';
    SJPMDItemMasterImportBatchService service = new SJPMDItemMasterImportBatchService();

    md31.initRow(FileA, 'ZT31TC16S001').setProcessingGroup(3).save();
    md31.initRow(FileA, 'ZT31TC16S002').setProcessingGroup(3).save();
    md31.initRow(FileA, 'ZT31TC16S003').setProcessingGroup(3).setStatus(SJPMDInventImportStatus::Error).save();
    md31.initRow(FileA, 'ZT31TC16S004').setProcessingGroup(4).save();
    md31.initRow(FileB, 'ZT31TC16S005').setProcessingGroup(3).save();

    this.assertEquals(2, int642int(service.countPendingRows(3, FileA)), 'Group 3 of file A: two New rows; the Error row does not count');
    this.assertEquals(1, int642int(service.countPendingRows(4, FileA)), 'Group 4 of file A');
    this.assertEquals(1, int642int(service.countPendingRows(3, FileB)), 'Group 3 of file B');
    this.assertEquals(0, int642int(service.countPendingRows(5, FileA)), 'A group without rows');
}

/// <summary>
/// TC17: countPendingRowsForExecutionIds, which the final task uses to report rows a run
/// left unprocessed, sums the New rows of the given execution ids and skips blank ids.
/// initRow uses the file name as the ExecutionId.
/// </summary>
[SysTestMethod]
public void tc17_countPendingRowsForExecutionIds_countsOnlyNew()
{
    const Filename FileA = 'TEST_MD31_TC17_A';
    const Filename FileB = 'TEST_MD31_TC17_B';

    md31.initRow(FileA, 'ZT31TC17S001').save();
    md31.initRow(FileA, 'ZT31TC17S002').setStatus(SJPMDInventImportStatus::Error).save();
    md31.initRow(FileB, 'ZT31TC17S003').save();

    this.assertEquals(2, int642int(SJPMDItemMasterImportBatchService::countPendingRowsForExecutionIds([FileA, FileB, ''])), 'New rows of both execution ids');
    this.assertEquals(1, int642int(SJPMDItemMasterImportBatchService::countPendingRowsForExecutionIds([FileA])), 'The Error row does not count');
    this.assertEquals(0, int642int(SJPMDItemMasterImportBatchService::countPendingRowsForExecutionIds(conNull())), 'No execution ids');
}

/// <summary>
/// TC18: another run holds the MD31 run lock. orchestrate - as a menu run calls it - refuses
/// to start instead of resetting and reassigning that run's processing groups.
/// </summary>
[SysTestMethod]
public void tc18_orchestrate_lockHeldByOtherRun_isRefused()
{
    SJPMDItemMasterImportContract contract;

    this.assertMd31Unlocked();
    this.assertTrue(SJPMDIntegrationRunLock::tryAcquire(#MD31LockScope, #MD31LockKey, newGuid(), 'TEST TC18 other run'),
        'Arrange: the other run takes the lock');

    contract = this.initContract('TEST_MD31_TC18');

    this.parmExceptionExpected(true, strFmt("@SJP:SJPMDIntegrationRunLockAlreadyHeld", #MD31LockScope, #MD31LockKey));

    new SJPMDItemMasterImportService().orchestrate(contract);
}

/// <summary>
/// TC19: the ADF path. createBatchHeaderAndTasks already took the lock with the contract's
/// RunId, so orchestrate accepts it; with no New rows for the file it releases the lock.
/// </summary>
[SysTestMethod]
public void tc19_orchestrate_ownLockWithoutRows_releasesLock()
{
    SJPMDItemMasterImportContract contract;

    this.assertMd31Unlocked();
    contract = this.initContract('TEST_MD31_TC19');
    this.assertTrue(SJPMDIntegrationRunLock::tryAcquire(#MD31LockScope, #MD31LockKey, contract.parmRunId(), 'TEST TC19 own run'),
        'Arrange: this run takes the lock, as createBatchHeaderAndTasks does');

    new SJPMDItemMasterImportService().orchestrate(contract);

    this.assertFalse(SJPMDIntegrationRunLock::isLocked(#MD31LockScope, #MD31LockKey), 'The run released its own lock');
}

/// <summary>
/// TC20: the menu path. No lock exists; orchestrate takes it for this run and, with no New
/// rows for the file, releases it again.
/// </summary>
[SysTestMethod]
public void tc20_orchestrate_withoutLock_acquiresAndReleases()
{
    SJPMDItemMasterImportContract contract;

    this.assertMd31Unlocked();
    contract = this.initContract('TEST_MD31_TC20');

    new SJPMDItemMasterImportService().orchestrate(contract);

    this.assertFalse(SJPMDIntegrationRunLock::isLocked(#MD31LockScope, #MD31LockKey), 'No lock is left behind');
}

/// <summary>
/// TC29: 20 SKUs on 8 threads. The split is even - the first 20 mod 8 = 4 groups take one
/// SKU more - and each group is a run of consecutive SKUs in sku_cd order.
/// </summary>
[SysTestMethod]
public void tc29_assignGroups_eightThreads_evenSplit()
{
    const Filename TestFile  = 'TEST_MD31_GRP_TC29';
    const str      SkuPrefix = 'ZT31TC29S';

    this.seedSkus(TestFile, SkuPrefix, 20);

    TEST_MD31GroupAssigningService::construct().assign(8, TestFile);

    this.assertGroupSizes(TestFile, SkuPrefix, [3, 3, 3, 3, 2, 2, 2, 2]);
}

/// <summary>
/// TC30: 1 thread. Every SKU goes to group 1.
/// </summary>
[SysTestMethod]
public void tc30_assignGroups_oneThread_allInGroupOne()
{
    const Filename TestFile  = 'TEST_MD31_GRP_TC30';
    const str      SkuPrefix = 'ZT31TC30S';

    this.seedSkus(TestFile, SkuPrefix, 5);

    TEST_MD31GroupAssigningService::construct().assign(1, TestFile);

    this.assertGroupSizes(TestFile, SkuPrefix, [5]);
}

/// <summary>
/// TC31: 16 threads for 5 SKUs. One group per SKU (5 groups), so no worker task is empty.
/// </summary>
[SysTestMethod]
public void tc31_assignGroups_moreThreadsThanSkus_oneSkuPerGroup()
{
    const Filename TestFile  = 'TEST_MD31_GRP_TC31';
    const str      SkuPrefix = 'ZT31TC31S';

    this.seedSkus(TestFile, SkuPrefix, 5);

    TEST_MD31GroupAssigningService::construct().assign(16, TestFile);

    this.assertGroupSizes(TestFile, SkuPrefix, [1, 1, 1, 1, 1]);
}

/// <summary>
/// TC32: 48 SKUs on 16 threads divide exactly: 16 groups of 3. The rounded-up group size of
/// the earlier version gave fewer groups than threads for counts such as 100 SKUs on 16.
/// </summary>
[SysTestMethod]
public void tc32_assignGroups_sixteenThreads_equalGroups()
{
    const Filename TestFile  = 'TEST_MD31_GRP_TC32';
    const str      SkuPrefix = 'ZT31TC32S';

    this.seedSkus(TestFile, SkuPrefix, 48);

    TEST_MD31GroupAssigningService::construct().assign(16, TestFile);

    this.assertGroupSizes(TestFile, SkuPrefix, [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3]);
}

/// <summary>
/// TC33: the rows of one SKU share a group and the SKU is counted once; a stale group on a
/// New row is reassigned; an Error row and a row of another file are left as they are.
/// File A has 4 New SKUs (S001 with two rows), so 2 threads give groups of 2 and 2.
/// </summary>
[SysTestMethod]
public void tc33_assignGroups_skuRowsStayTogether_scopeRespected()
{
    const Filename FileA = 'TEST_MD31_GRP_TC33_A';
    const Filename FileB = 'TEST_MD31_GRP_TC33_B';

    md31.initRow(FileA, 'ZT31TC33S001').setCompanyCode('TEST1').save();
    md31.initRow(FileA, 'ZT31TC33S001').setCompanyCode('TEST2').save();
    md31.initRow(FileA, 'ZT31TC33S002').save();
    md31.initRow(FileA, 'ZT31TC33S003').save();
    md31.initRow(FileA, 'ZT31TC33S004').setProcessingGroup(7).save();
    md31.initRow(FileA, 'ZT31TC33S005').setProcessingGroup(9).setStatus(SJPMDInventImportStatus::Error).save();
    md31.initRow(FileB, 'ZT31TC33S006').save();

    TEST_MD31GroupAssigningService::construct().assign(2, FileA);

    this.assertEquals(1, this.groupOf(FileA, 'ZT31TC33S001', 'TEST1'), 'S001, first row');
    this.assertEquals(1, this.groupOf(FileA, 'ZT31TC33S001', 'TEST2'), 'S001, second row: same group as the first');
    this.assertEquals(1, this.groupOf(FileA, 'ZT31TC33S002'), 'S002: the SKU with two rows counts once, so S002 completes group 1');
    this.assertEquals(2, this.groupOf(FileA, 'ZT31TC33S003'), 'S003');
    this.assertEquals(2, this.groupOf(FileA, 'ZT31TC33S004'), 'S004: the stale group 7 is reassigned');
    this.assertEquals(9, this.groupOf(FileA, 'ZT31TC33S005'), 'S005: an Error row is not touched');
    this.assertEquals(0, this.groupOf(FileB, 'ZT31TC33S006'), 'S006: a row of another file is not touched');
}

/// <summary>
/// TC34: the contract accepts 1 to MaxNumOfThreads (32) threads and rejects 0 and 33.
/// orchestrate caps larger values from the ADF path, which skips validate; that path needs
/// a batch job and is checked in the sandbox.
/// </summary>
[SysTestMethod]
public void tc34_contractValidate_threadCountBetweenOneAndMax()
{
    SJPMDItemMasterImportContract contract = new SJPMDItemMasterImportContract();

    this.assertEquals(32, SJPMDItemMasterImportContract::MaxNumOfThreads, 'The agreed maximum');

    contract.parmNumOfThreads(0);
    this.assertFalse(contract.validate(), '0 threads');

    contract.parmNumOfThreads(1);
    this.assertTrue(contract.validate(), '1 thread');

    contract.parmNumOfThreads(SJPMDItemMasterImportContract::MaxNumOfThreads);
    this.assertTrue(contract.validate(), 'The maximum');

    contract.parmNumOfThreads(SJPMDItemMasterImportContract::MaxNumOfThreads + 1);
    this.assertFalse(contract.validate(), 'One above the maximum');
}

/// <summary>
/// One New input row for each of _count SKUs: _skuPrefix + 001, 002, ...
/// </summary>
private void seedSkus(Filename _fileName, str _skuPrefix, int _count)
{
    int i;

    for (i = 1; i <= _count; i++)
    {
        md31.initRow(_fileName, this.skuCode(_skuPrefix, i)).save();
    }
}

private SJPMDItemMasterJANCode skuCode(str _skuPrefix, int _number)
{
    return _skuPrefix + strRFix(int2Str(_number), 3, '0');
}

/// <summary>
/// The SKUs seeded by seedSkus fill groups 1, 2, ... in sku_cd order with the given sizes,
/// and no other group exists for the file.
/// </summary>
private void assertGroupSizes(Filename _fileName, str _skuPrefix, container _groupSizes)
{
    SJPMDItemMaster itemMaster;
    int             expectedGroup = 1;
    int             skusInGroup   = 0;
    int             skuCount      = 0;
    int             groupSize;
    int             i;

    for (i = 1; i <= conLen(_groupSizes); i++)
    {
        groupSize = conPeek(_groupSizes, i);
        skuCount += groupSize;
    }

    for (i = 1; i <= skuCount; i++)
    {
        groupSize = conPeek(_groupSizes, expectedGroup);

        if (skusInGroup == groupSize)
        {
            expectedGroup++;
            skusInGroup = 0;
        }

        skusInGroup++;

        this.assertEquals(expectedGroup, this.groupOf(_fileName, this.skuCode(_skuPrefix, i)),
            strFmt('Group of SKU %1', this.skuCode(_skuPrefix, i)));
    }

    select maxof(ProcessingGroup) from itemMaster
        where itemMaster.file_name == _fileName;

    this.assertEquals(conLen(_groupSizes), itemMaster.ProcessingGroup, 'Number of groups');
}

/// <summary>
/// The processing group of a SKU's input row; _companyCode picks one of several rows.
/// </summary>
private int groupOf(Filename _fileName, SJPMDItemMasterJANCode _sku, SJPMDItemMasterCompanyCode _companyCode = '')
{
    SJPMDItemMaster itemMaster;

    select firstonly RecId, ProcessingGroup from itemMaster
        where itemMaster.file_name == _fileName
           && itemMaster.sku_cd    == _sku
           && (!_companyCode || itemMaster.crp_cd == _companyCode);

    this.assertTrue(itemMaster.RecId != 0, strFmt('No input row for SKU %1', _sku));

    return itemMaster.ProcessingGroup;
}

/// <summary>
/// A contract for one file with its own RunId, as a new menu or ADF run has.
/// </summary>
private SJPMDItemMasterImportContract initContract(Filename _fileName)
{
    SJPMDItemMasterImportContract contract = new SJPMDItemMasterImportContract();

    contract.parmFileName(_fileName);
    contract.parmNumOfThreads(1);
    contract.parmRunId(newGuid());

    return contract;
}

/// <summary>
/// TC39: input rows left New by an earlier run keep the ProcessingGroup it gave them. The
/// ADF entry point SJPBatchJobService.start must still count them and schedule the MD31 batch
/// job, so that "run the batch again" works through ADF. Before the fix it counted only rows
/// of group 0 and scheduled nothing. The job and the run lock are rolled back with the test.
/// </summary>
[SysTestMethod]
public void tc39_adfStart_picksUpRowsWithAssignedGroup()
{
    const Filename              TestFile = 'TEST_MD31_TC39';
    SJPBatchJobRequestContract  request  = new SJPBatchJobRequestContract();
    SJPBatchJobResponseContract response;
    BatchJob                    batchJob;
    Batch                       batch;
    RefRecId                    lastJobId;
    str                         message;

    this.assertMd31Unlocked();

    md31.initRow(TestFile, 'ZT31TC39S001').setProcessingGroup(2).save();
    md31.initRow(TestFile, 'ZT31TC39S002').setProcessingGroup(3).save();

    select maxof(RecId) from batchJob
        where batchJob.RecId > 0;
    lastJobId = batchJob.RecId;

    request.parmBatchId('31');
    request.parmFileName(TestFile);
    request.parmNumOfTasks(1);
    request.parmDataAreaId(curExt());
    response = new SJPBatchJobService().start(request);
    message  = response.parmMessage();

    this.assertEquals(0, response.parmRet(), message);
    this.assertTrue(strScan(message, 'Item master record count: 2', 1, strLen(message)) > 0,
        strFmt('Both rows are counted. Message: %1', message));

    select firstonly RecId from batchJob
        where batchJob.RecId > lastJobId
        exists join batch
            where batch.BatchJobId == batchJob.RecId
               && batch.Caption    == "@SJP:MDItemMasterImportBatch_Caption";
    this.assertTrue(batchJob.RecId != 0, 'The MD31 batch job is scheduled');
}

/// <summary>
/// TC40: the MD31 volume verifier must FAIL when the process lost a row. Seeds 3 SKUs, then
/// archives only 2 of them (as MD31 would, without products). The verifier compares with the
/// seed's record in the ExecutionId, so it reports "2 of 3 seeded rows found".
/// </summary>
[SysTestMethod]
public void tc40_volumeVerify_lostRow_fails()
{
    const Filename TestFile = 'TEST_MD31_TC40';
    str            verdict;

    TEST_MD31VolumeSeedJob::seed(3, TestFile);
    this.archiveLikeMD31(TestFile, true, 0);

    verdict = TEST_MD31VolumeVerifyJob::verify(TestFile);

    this.assertEquals('FAIL', subStr(verdict, 1, 4), verdict);
    this.assertTrue(strScan(verdict, '2 of 3 seeded rows found', 1, strLen(verdict)) > 0, verdict);
}

/// <summary>
/// TC41: the MD31 volume verifier must FAIL when an input price changed on the way. Seeds 3
/// SKUs and archives all of them, one with its price 1 higher: the rows match the seed, but
/// the total price does not.
/// </summary>
[SysTestMethod]
public void tc41_volumeVerify_changedPrice_fails()
{
    const Filename TestFile = 'TEST_MD31_TC41';
    str            verdict;

    TEST_MD31VolumeSeedJob::seed(3, TestFile);
    this.archiveLikeMD31(TestFile, false, 1);

    verdict = TEST_MD31VolumeVerifyJob::verify(TestFile);

    this.assertEquals('FAIL', subStr(verdict, 1, 4), verdict);
    this.assertTrue(strScan(verdict, 'total price', 1, strLen(verdict)) > 0, verdict);
    this.assertTrue(strScan(verdict, 'seeded rows found', 1, strLen(verdict)) == 0,
        strFmt('All rows are there, so the row check passes. Verdict: %1', verdict));
}

/// <summary>
/// Does to the file's input rows what MD31 does after creating the products, without them:
/// copies them to SJPMDItemMasterArchive as Created and deletes them from the input.
/// _loseOne leaves the first SKU out of the archive; _priceDelta is added to the first SKU's
/// price.
/// </summary>
private void archiveLikeMD31(Filename _fileName, boolean _loseOne, real _priceDelta)
{
    SJPMDItemMaster        itemMaster;
    SJPMDItemMaster        itemMasterDelete;
    SJPMDItemMasterArchive archive;
    int                    rowNumber = 0;

    ttsbegin;
    while select itemMaster
        order by itemMaster.sku_cd
        where itemMaster.file_name == _fileName
    {
        rowNumber++;

        if (rowNumber == 1 && _loseOne)
        {
            continue;
        }

        archive.clear();
        archive.crp_cd      = itemMaster.crp_cd;
        archive.sku_cd      = itemMaster.sku_cd;
        archive.sku_name_en = itemMaster.sku_name_en;
        archive.sku_name_lc = itemMaster.sku_name_lc;
        archive.price       = itemMaster.price + (rowNumber == 1 ? _priceDelta : 0);
        archive.file_name   = itemMaster.file_name;
        archive.ExecutionId = itemMaster.ExecutionId;
        archive.Status      = SJPMDInventImportStatus::Created;
        archive.insert();
    }

    delete_from itemMasterDelete
        where itemMasterDelete.file_name == _fileName;
    ttscommit;
}

/// <summary>
/// The run lock is shared by all companies: a real MD31 run in progress would make the
/// lock tests meaningless, so stop at Arrange instead.
/// </summary>
private void assertMd31Unlocked()
{
    this.assertFalse(SJPMDIntegrationRunLock::isLocked(#MD31LockScope, #MD31LockKey),
        'Arrange: an MD31 run holds the run lock in this environment; run the test when it has finished');
}

